#include <bits/stdc++.h>

using namespace std;


const int N = 2e5 + 100;
vector <pair <int, int>> g[N];
int val[N];

vector <int> ans;
map <int, int> cnt1, cnt2;
set <int> mad1, mad2;

vector <int> path, path_ind;
bool used[N];


bool dfs(int v, int tar) {
    used[v] = true;
    path.push_back(v);
    if (v == tar) {
        return true;
    }
    for (auto [i, ind] : g[v]) {
        if (!used[i]) {
            path_ind.push_back(ind);
            if (dfs(i, tar)) {
                return true;
            }
            path_ind.pop_back();
        }
    }
    path.pop_back();
    return false;
}


int mad() {
    int mx = 0;
    if (!mad1.empty()) {
        mx = max(mx, *mad1.rbegin());
    }
    if (!mad2.empty()) {
        mx = max(mx, *mad2.rbegin());
    }
    return mx;
}


void recalc(int v, int ban1, int ban2) {
    cnt1[val[v]]++;
    if (cnt1[val[v]] == 2) {
        mad1.insert(val[v]);
    }
    cnt2[val[v]]--;
    if (cnt2[val[v]] == 1) {
        mad2.erase(val[v]);
    }
    for (auto [i, _] : g[v]) {
        if (i != ban1 && i != ban2) {
            recalc(i, v, -1);
        }
    }
}


